/** Look a figure up by its number ("5.12", "Figure 5.12", "fig. 5.12") or its anchor id ("fig-std-offer-equil"). */
export function lookupFigure(q: string): FigureData | null {
  const s = String(q ?? "").trim().toLowerCase().replace(/^(figure|fig\.?)\s*(?=[a-z]?\.?\d)/, "");
  for (const f of Object.values(FIGURES)) if (f.num.toLowerCase() === s || f.id.toLowerCase() === s) return f;
  return null;
}
/** One line per figure for the tool description, so the model can choose without a lookup round trip. */
export const figureIndex = (): string => Object.values(FIGURES).map((f) => `${f.num} ${f.title.slice(0, 70)}`).join("; ");
